BloomSource = ApplyBloomThreshold(SceneColor);

Bloom1 = GaussianBlur(Downsample(BloomSource, 2));
Bloom2 = GaussianBlur(Downsample(BloomSource, 4));
Bloom3 = GaussianBlur(Downsample(BloomSource, 8));
Bloom4 = GaussianBlur(Downsample(BloomSource, 16));
Bloom5 = GaussianBlur(Downsample(BloomSource, 32));

Bloom = Bloom1 * Weight1
      + Bloom2 * Weight2
      + Bloom3 * Weight3
      + Bloom4 * Weight4
      + Bloom5 * Weight5;

FinalHDR = SceneColor + Bloom * BloomIntensity;

SceneFrequency  = FFT(BloomSource);
KernelFrequency = FFT(BloomKernel);

BloomFrequency = SceneFrequency * KernelFrequency;
Bloom = IFFT(BloomFrequency);

FinalHDR = SceneColor + Bloom;
